INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47361, 'Jeremiah 44:21', 'Jeremiah', 44, 21, '”ولې ستاسو هم دا خيال دے چې ګنې مالِک خُدائ ته دا پته نشته څۀ چې تاسو او ستاسو پلار نيکۀ، ستاسو بادشاهانو او سرکارى کسانو، او ټولو خلقو بُتانو ته د يهوداه په ښارونو او د يروشلم په کوڅو کښې خوشبوئى سوزولې ده؟', '”ولې ستاسو هم دا خیال دے چې ګنې مالک خدای ته دا پته نشته چۀ چې تاسو او ستاسو پلار نیکۀ، ستاسو بادشاهانو او سرکاری کسانو، او تولو خلقو بتانو ته د یهوداه په شارونو او د یروشلم په کوچو کشې خوشبویی سوزولې ده؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47362, 'Jeremiah 44:22', 'Jeremiah', 44, 22, 'دا ځکه وشُو چې، نور مالِک خُدائ ستاسو د شرارت نه ډک او حرام کارونه نۀ شو برداشت کولے، نو د دې په وجه ستاسو زمکه د لعنت مثال وګرځېده، او په صحرا او کنډرو بدله شوه چې تر ننه پورې هيڅ څوک په کښې نۀ اوسيږى.', 'دا جکه وشو چې، نور مالک خدای ستاسو د شرارت نه دک او حرام کارونه نۀ شو برداشت کولے، نو د دې په وجه ستاسو زمکه د لعنت مثال وګرجېده، او په صحرا او کندرو بدله شوه چې تر ننه پورې هیچ چوک په کشې نۀ اوسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47363, 'Jeremiah 44:23', 'Jeremiah', 44, 23, 'دا مصيبتونه ځکه په تاسو باندې راغلل چې تاسو بُتانو ته خوشبو وسوزوله او د مالِک خُدائ خلاف مو ګناه وکړه. تاسو د هغۀ د حکمونو منلو نه اِنکار وکړو او نۀ مو د هغۀ په لارښودنو، اصُولو او شريعت باندې عمل وکړو.“', 'دا مصیبتونه جکه په تاسو باندې راغلل چې تاسو بتانو ته خوشبو وسوزوله او د مالک خدای خلاف مو ګناه وکره. تاسو د هغۀ د حکمونو منلو نه انکار وکرو او نۀ مو د هغۀ په لارشودنو، اصولو او شریعت باندې عمل وکرو.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47364, 'Jeremiah 44:24', 'Jeremiah', 44, 24, 'نو بيا يرمياه ټولو ناريناؤ او زناناؤ ته وفرمائيل چې، ”اے د يهوداه خلقو تاسو څوک چې په مِصر کښې اوسېږئ د مالِک خُدائ کلام ته غوږ ونيسئ.', 'نو بیا یرمیاه تولو ناریناو او زناناو ته وفرماییل چې، ”اے د یهوداه خلقو تاسو چوک چې په مصر کشې اوسېزی د مالک خدای کلام ته غوز ونیسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47365, 'Jeremiah 44:25', 'Jeremiah', 44, 25, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، تاسو او ستاسو ښځو ووئيل چې، مونږ به ضرور خپلې وعدې پوره کوُو او آسمانې مَلِکې ته به د خوشبو سوزولو او د څښلو نذرانې پېش کوُو. نو تاسو چې څۀ کول نو هغه وکړئ او خپله وعده او منښته هغې ته پوره کړئ.', 'مالک خدای رب الافواج د بنی اسراییلو خدای پاک داسې فرمایی چې، تاسو او ستاسو شجو ووییل چې، مونز به ضرور خپلې وعدې پوره کوو او اسمانې ملکې ته به د خوشبو سوزولو او د چشلو نذرانې پېش کوو. نو تاسو چې چۀ کول نو هغه وکری او خپله وعده او منشته هغې ته پوره کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47366, 'Jeremiah 44:26', 'Jeremiah', 44, 26, 'خو اوس تاسو ټول د مالِک خُدائ دې پېغام ته غوږ ونيسئ، تاسو د يهوداه ټولو خلقو څوک چې اوس په مِصر کښې اوسېږئ، زۀ په ژوندى مالِک قادر مطلق خُدائ قسم خورم، مالِک خُدائ فرمائى چې، زما نوم به نور هيڅکله په مِصر کښې د يو يهودى په خولۀ وانۀ خستلے شى. په تاسو کښې به يو هم زما نوم د دُعا او د قسم خوړلو دپاره استعمال نۀ کړى، هغه دا چې، په يقين سره مالِک قادر مطلق خُدائ ژوندے دے.', 'خو اوس تاسو تول د مالک خدای دې پېغام ته غوز ونیسی، تاسو د یهوداه تولو خلقو چوک چې اوس په مصر کشې اوسېزی، زۀ په ژوندی مالک قادر مطلق خدای قسم خورم، مالک خدای فرمایی چې، زما نوم به نور هیچکله په مصر کشې د یو یهودی په خولۀ وانۀ خستلے شی. په تاسو کشې به یو هم زما نوم د دعا او د قسم خورلو دپاره استعمال نۀ کری، هغه دا چې، په یقین سره مالک قادر مطلق خدای ژوندے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47367, 'Jeremiah 44:27', 'Jeremiah', 44, 27, 'زۀ به په تاسو ضرور افتونه نازل کړم، نه چې آبادى. د يهوداه هر يو کس څوک چې اوس په مِصر کښې اوسيږى ټول به جنګ او يا په قحط کښې مړۀ شى ترڅو چې يو هم ژوندے پاتې نۀ شى.', 'زۀ به په تاسو ضرور افتونه نازل کرم، نه چې ابادی. د یهوداه هر یو کس چوک چې اوس په مصر کشې اوسیزی تول به جنګ او یا په قحط کشې مرۀ شی ترچو چې یو هم ژوندے پاتې نۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47368, 'Jeremiah 44:28', 'Jeremiah', 44, 28, 'صرف يو څو کسان به د مرګ نه وتښتى او د مِصر نه به يهوداه ته واپس شى. نو بيا ټول هغه کسان چې مِصر ته راغلى دى نو هغوئ ته به دا پته ولګى چې د چا خبره رښتيا ده، زما او کۀ د هغوئ.', 'صرف یو چو کسان به د مرګ نه وتشتی او د مصر نه به یهوداه ته واپس شی. نو بیا تول هغه کسان چې مصر ته راغلی دی نو هغوی ته به دا پته ولګی چې د چا خبره رشتیا ده، زما او کۀ د هغوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47369, 'Jeremiah 44:29', 'Jeremiah', 44, 29, 'مالِک خُدائ فرمائى چې، دا به تاسو دپاره نښه وى چې زۀ په دې ځائ کښې تاسو ته سزا درکړم، نو تاسو به په دې پوهه شئ چې ما ستاسو خلاف صرف خبرې نۀ دى کړې بلکې ضرور به سزا هم درکوم.', 'مالک خدای فرمایی چې، دا به تاسو دپاره نشه وی چې زۀ په دې جای کشې تاسو ته سزا درکرم، نو تاسو به په دې پوهه شی چې ما ستاسو خلاف صرف خبرې نۀ دی کرې بلکې ضرور به سزا هم درکوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47370, 'Jeremiah 44:30', 'Jeremiah', 44, 30, 'مالِک خُدائ فرمائى چې، لکه څنګه چې ما د يهوداه بادشاه صدقياه د بابل بادشاه نبوکدنضر ته حواله کړو، دغه شان به زۀ د فِرعون حفرع د مِصر بادشاه هم د هغۀ دشمنانو ته حواله کړم څوک چې د دۀ مرګ پسې ګرځى.“', 'مالک خدای فرمایی چې، لکه چنګه چې ما د یهوداه بادشاه صدقیاه د بابل بادشاه نبوکدنضر ته حواله کرو، دغه شان به زۀ د فرعون حفرع د مصر بادشاه هم د هغۀ دشمنانو ته حواله کرم چوک چې د دۀ مرګ پسې ګرجی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_44_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47371, 'Proverbs 25:1', 'Proverbs', 25, 1, 'دا هم د سلیمان هغه متلونه دي چې د یهودا د پاچا حزقیا کاتبانو راټول کړي دي.', 'دا هم د سلیمان هغه متلونه دی چې د یهودا د پاچا حزقیا کاتبانو راتول کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_001.mp3', 'https://drive.google.com/file/d/1e9DrBOkVM_ezwblDxaHUxKcpKS7_Z7Id/preview', 1761237844, 1761237844),
(47372, 'Proverbs 25:2', 'Proverbs', 25, 2, 'دا د خدای لویي ده چې رازونه پټ ساتي د یوې موضوع څېړل د پاچا لویي ښکاره کوي.', 'دا د خدای لویی ده چې رازونه پت ساتی د یوې موضوع چېرل د پاچا لویی شکاره کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_002.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1v_ZaxhLa9OtZVYkykOeHMi7uc59XrJCS&export=download', 1761237844, 1761237844),
(47373, 'Proverbs 25:3', 'Proverbs', 25, 3, 'لکه څنګه چې اسمان لوړ او ځمکه ژوره ده همداسې د پاچاهانو د زړونو رازونه هم پټ دي.', 'لکه چنګه چې اسمان لور او جمکه ژوره ده همداسې د پاچاهانو د زرونو رازونه هم پت دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_003.mp3', 'https://drive.google.com/file/d/1Dz0cNVOeIeJv25A_S8Dhj5ZrJflpmQqe/preview', 1761237844, 1761237844),
(47374, 'Proverbs 25:4', 'Proverbs', 25, 4, 'د سپینو زرو نه ناپاکي لېرې کړه چې زرګر ترې ښایسته لوښی جوړ کړي.', 'د سپینو زرو نه ناپاکی لېرې کره چې زرګر ترې شایسته لوشی جور کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_004.mp3', 'https://drive.google.com/file/d/1R0SGGaKzfKpa3tXTouCBVF1REKpHS_ps/preview', 1761237844, 1761237844),
(47375, 'Proverbs 25:5', 'Proverbs', 25, 5, 'د پاچا له حضور نه بدکاران لېرې کړه چې تخت یې د عدالت په بنیاد ټینګ پاتې شي.', 'د پاچا له حضور نه بدکاران لېرې کره چې تخت یې د عدالت په بنیاد تینګ پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_005.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1NWpOEmv2hH0Gdf8HP-5IYo2GRA072iLY&export=download', 1761237844, 1761237844),
(47376, 'Proverbs 25:6', 'Proverbs', 25, 6, 'د پاچا په حضور کې ځان لوړ مه ګڼه او د لویو خلکو په ځای مه کښېنه', 'د پاچا په حضور کې جان لور مه ګنه او د لویو خلکو په جای مه کشېنه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_006.mp3', 'https://drive.google.com/file/d/1tV2buy-hhqciZs0CyvtYXMD2ly4V4qS3/preview', 1761237844, 1761237844),
(47377, 'Proverbs 25:7', 'Proverbs', 25, 7, 'نو دا به ښه وي چې هغه تاته ووایي: «راشه او زما په خوا کې کښېنه» له دې نه چې د مشرانو په مخکې دې سپک کړي او په لاندې ځای کې دې کښېنوي. څه چې تا په خپلو سترګو لیدلي دي', 'نو دا به شه وی چې هغه تاته ووایی: «راشه او زما په خوا کې کشېنه» له دې نه چې د مشرانو په مخکې دې سپک کری او په لاندې جای کې دې کشېنوی. چه چې تا په خپلو سترګو لیدلی دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_007.mp3', 'https://drive.google.com/file/d/10t9z4eWuFuzsX7jta_lGVtQdtrVg6hJN/preview', 1761237844, 1761237844),
(47378, 'Proverbs 25:8', 'Proverbs', 25, 8, 'نو په محکمه کې په ویلو بیړه مه کوه هسې نه چې تا ملامته او بیا دې رسوا کړي. که داسې وشي نو په اخر کې به ته څه کوې؟', 'نو په محکمه کې په ویلو بیره مه کوه هسې نه چې تا ملامته او بیا دې رسوا کری. که داسې وشی نو په اخر کې به ته چه کوې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_008.mp3', 'https://drive.google.com/file/d/1CWTRLZ6dMfTsrcHxTNtg5IDnaLGySHi7/preview', 1761237844, 1761237844),
(47379, 'Proverbs 25:9', 'Proverbs', 25, 9, 'په یوه دعوه کې د هرچا سره مخامخ بحث کوه او د بل چا راز ورته مه ښکاره کوه', 'په یوه دعوه کې د هرچا سره مخامخ بحث کوه او د بل چا راز ورته مه شکاره کوه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_009.mp3', 'https://drive.google.com/file/d/1_opJWVPw4FSnlTxOJcdP_nxS2pJe7jvm/preview', 1761237844, 1761237844),
(47380, 'Proverbs 25:10', 'Proverbs', 25, 10, 'هسې نه چې څوک یې واوري او تا وشرموي او بدنامي به دې هېڅکله ختمه نه شي.', 'هسې نه چې چوک یې واوری او تا وشرموی او بدنامی به دې هېچکله ختمه نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_010.mp3', 'https://drive.google.com/file/d/1hyOcaTSapk3CPcamv4tPWOLJ8F-fAtHV/preview', 1761237844, 1761237844),
(47381, 'Proverbs 25:11', 'Proverbs', 25, 11, 'په ځای خبره داسې ده لکه د سپینو زرو په ګاڼه کې چې د سرو زرو مرۍ وي.', 'په جای خبره داسې ده لکه د سپینو زرو په ګانه کې چې د سرو زرو مری وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_011.mp3', 'https://drive.google.com/file/d/1b6cJOAk51OVwrXYJ-nDTwyB9sC3qw8RH/preview', 1761237844, 1761237844),
(47382, 'Proverbs 25:12', 'Proverbs', 25, 12, 'د حکمت د خاوند نصیحت، اورېدونکي ته داسې دی لکه په غوږ کې د خالصو سرو زرو غوږوالۍ او یا ګاڼه وي.', 'د حکمت د خاوند نصیحت، اورېدونکی ته داسې دی لکه په غوز کې د خالصو سرو زرو غوزوالی او یا ګانه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_012.mp3', 'https://drive.google.com/file/d/1-xKt-RYUVhG04BRO3kdQcBbJt7Cdb66_/preview', 1761237844, 1761237844),
(47383, 'Proverbs 25:13', 'Proverbs', 25, 13, 'صادق استازی د خپل لېږونکي دپاره داسې دی لکه د لو په وخت کې چې د غرونو د واورې یخوالی وي چې د خپل بادار روح تازه کوي.', 'صادق استازی د خپل لېزونکی دپاره داسې دی لکه د لو په وخت کې چې د غرونو د واورې یخوالی وی چې د خپل بادار روح تازه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs025_verse_013.mp3', 'https://drive.google.com/file/d/1KngHKe33ebtyvBzJGEDpid-_H8y0VA8M/preview', 1761237844, 1761237844),
